				["¡Maldito sea Firallon! No podría navegar un esquife por el Lago de Cristal y mucho de atraque de Firallon y asesinad al líder Velasangre. Su flota se hundirá poco después..."] = 608,
			},
			["Primer oficial Crazz"] = {
				["Parece que tienes muchas ganas de ponerte a trabajar, colega. No tengo muy claro por norte de la Bahía del Botín en La Costa Salvaje, a ver lo que descubres."] = 595,
				["¡Voto a bríos! ¿Así que los Bucaneros Velasangre están planeando atacar la Bahía del Botín? flota Cuernomarino inmediatamente. Ese viejo lobo de mar está por la ciudad, en alguna parte..."] = 599,
			},
		},
