		["Componentes importantes"] = {
			["Bodley"] = {
				["$C, escucha atentamente. Ahora que tenemos el blandón y los medios para encenderlo, aún necesitamos de la Cuna del Invierno, que realizan incursiones hacia el norte de vez en cuando."] = 8963,
				["$C, escucha atentamente. Ahora que tenemos el blandón y los medios para encenderlo, aún necesitamos de la Peste del Este y recupera una espada luminosa de zelote de los pretorianos."] = 8964,
				["$C, escucha atentamente. Ahora que tenemos el blandón y los medios para encenderlo, aún necesitamos druidas de los silítidos que viven en los alrededores de Colmen'Regal al sureste de Silithus."] = 8962,
				["$C, escucha atentamente. Ahora que tenemos el blandón y los medios para encenderlo, aún necesitamos hasta allí y de entre sus restos recupera unas cenizas de almas de los Desterrados."] = 8965,
			},
		},
		["Componentes para Reivindicadores y Cía."] = {
			["Kreldig Ungor"] = {
				["Estos son los últimos objetos y, no te voy a mentir, no es un grupito que tiene que ser capitán o señor. Sencillito, ¿eh? Oyee... si prefieres pasar, lo entiendo."] = 1466,
				["Lo siguiente de la lista de Zurdibrujo es... veamos... mmm. Ah, aquí está. Es simple. maduro, no de uno anciano o moribundo. ¡Magos! De verdad, a veces piden unas cosas..."] = 1459,
				["Si quieres que te paguen, tendrás que volver a Forjaz y hablar con Roetten en te preocupes, hablaré bien de ti cuando vuelva. No debería quedarme mucho más en Desolace."] = 1467,
				["Uno de mis cometidos es recoger componentes para Zurdibrujo, un mago gnomo de Kharanos. Roetten que están al este de aquí. Tráemelos y seguiremos con el resto de la lista."] = 1458,
			},
		},
