		["Contar el tiempo"] = {
			["Cromi"] = {
				["Necesito que vayas al mundo que hay más allá de esta habitación, $N. Deja que encontrar en cajas fuertes dentro de los edificios en ruinas de esta ciudad antaño gloriosa."] = 4972,
				["Si quieres ayudarme una vez más, me serás muy útil. Estaría encantada de tener todos de esos relojes te daré un objeto que sospecho encontrarás bastante útil en el futuro."] = 4973,
