		["Corona de la Voluntad"] = {
			["Melisara"] = {
				["Ahora solo falta ir a Entrañas para entregarle la corona a Sharlindra. Ella se ocupará debes usarla para tus propios fines, $n; recuerda lo que le ha pasado a Mug'Thol."] = 521,
				["Con los tenientes de Mug'Thol muertos, ya solo queda matar a Mug'Thol y hacerse con a Mug'Thol y tráeme su cabeza y su corona. La resistencia Aplastacresta tiene que terminar."] = 520,
				["Mug'Thol y sus ogros Aplastacresta han invadido las ruinas de Alterac. Tenemos que reducir sus reducir sus filas si queremos castigarlo. Primero los debilitamos y después procedemos, ¿entendido? Bien. Adelante."] = 518,
				["Targ, Muckrake y Glommus son los generales de Mug'Thol. Le son leales, aunque quién sabe sus cabezas, $n, y después solo quedará separar a Mug'Thol de la suya, corona incluida."] = 519,
			},
		},
