		["Criatura marina varada"] = {
			[""] = {
				["El cadáver, que parece ser de una especie de mamífero marino, yace medio destripado en saqueado los restos, queda suficiente para reunir una muestra adecuada para Gwennyth Bly'Leggonde de Auberdine."] = 4728,
				["El cuerpo medio devorado de lo que podría ser un gigante mamífero marino yace en de la criatura para llevar una muestra de sus huesos a Gwennyth Bly'Leggonde a Auberdine."] = 4730,
				["En la costa de Cabo de la Niebla yacen los restos de un trillador gigante... para coger una muestra y llevársela a Gwennyth Bly'Leggonde de Auberdine para que la estudie."] = 4723,
				["Los restos de lo que parece ser un trillador gigante han aparecido encallados en una sido rapiñada, quedan suficientes restos para reunir una muestra adecuada para Gwennyth Bly'Leggonde de Auberdine."] = 4733,
