		["Domesticar la bestia"] = {
			["Dazalar"] = {
				["Ahora tienes el poder de domar una mascota, pero también debes adquirir las habilidades necesarias a nuevas promesas. Trátala con respeto y ella hará lo mismo contigo. Buena suerte, $n."] = 6103,
				["Al ser $gcazador:cazadora; es muy importante que recuerdes la responsabilidad que tienes en tus manos. la que podrás domar a un rondador Tejemadera. Dómalo y practica tus habilidades como $gcazador:cazadora;."] = 6063,
				["Has domado a dos criaturas terrestres y ahora debes domar a una criatura de los al mismo tiempo que tú. También te enseñaré a llamarlo y a retirarlo cuando quieras."] = 6102,
				["La naturaleza está en continuo cambio, $N. En este sentido, es algo predecible. Las tareas Entonces empezarás a comprender las similitudes y las diferencias que se dan en la naturaleza."] = 6101,
			},
			["Grif Corazón Salvaje"] = {
				["A lo mejor prefieres una criatura con más fuerza bruta. Los osos zarpahelada son excelentes y ganará experiencia al mismo tiempo que tú. También te enseñaré a llamarlo y despedirlo."] = 6085,
				["Son unas bestias bastante aparatosas; quizás prefieras algo más pequeño. Muy bien, tengo lo que de domador y a ver qué tal te va con un leopardo de las nieves."] = 6084,
				["¡Buenas, $Gchaval:chavala;! Supongo que quieres saber cómo conseguir una mascota. Muy bien, vamos a ello. cuál te gusta más. Busca un jabalí montés y dómalo con la fusta de domador."] = 6064,
			},
			["Guin Crinafilada"] = {
				["Para los tauren es importante seguir la tradición ancestral de luchar contra criaturas poderosas. Al práctica. Para empezar, usa esta fusta de domador para domar un zancudo de llanura adulto."] = 6061,
				["Tienes un espíritu indomable, siempre abierto a los desafíos. Ahora debes ganarte la confianza de fuerza indivisible. Ten la fusta de domador, $N. Practica amaestrando a un acechador de pradera."] = 6087,
				["Tu última tarea será amaestrar a una criatura de los cielos. El aguilón es un y ganará experiencia al mismo tiempo que tú. También te enseñaré a llamarlo y despedirlo."] = 6088,
			},
			["Thotar"] = {
				["La ventaja que te concede una mascota frente a tus rivales es de sobra conocida, un correspuma, un enérgico cangrejo. Utiliza la fusta para domarlo y luego practica tus habilidades."] = 6083,
				["La última criatura que debes domar es una a la que deberías intentar emular: el vez que lo haces tú. Y también te enseñaré cómo llamarla y despedirla a placer."] = 6082,
				["Someter a la naturaleza a tu autoridad es una habilidad admirable. Como $gcazador:cazadora;, debes esforzarte tus habilidades de combate con el jabalí a tu lado y luego vuelve a verme."] = 6062,
			},
		},
		["Domina el raptor"] = {
			["Hemet Decautela"] = {
				["Ahora aumentemos la dificultad del desafío y veamos si estás a la altura. Entra en Entra en la jungla y mata 10 de esos asquerosos raptores colazote. ¡Veamos si puedes!"] = 195,
				["Como has demostrado ser invencible en la selva, te hablaré de un feroz raptor que a Tethis y tráeme su garra. Sería un logro que ningún otro cazador ha conseguido."] = 197,
				["Veamos qué tal lo haces en este desafío. Ahí fuera hay una raza muy reservada Mata 10 acechadores de la selva y te enseñaré la mejor parte de la caza."] = 196,
				["¿Así que crees que tus habilidades de caza están en buena forma? Veamos si es no, no te diré dónde encontrarlos! Localizar a las bestias es la mitad del desafío."] = 194,
			},
		},
		["Domina el tigre"] = {
			["Ajeck Rouack"] = {
				["Ahora voy a subir las apuestas y a poner a prueba realmente tu habilidad. Demuéstrame no solo son los más difíciles de encontrar, sino también los más difíciles de vencer."] = 187,
				["Cuando yo era una niña, mi padre me enseñó a cazar tigres. Verás que los tus habilidades de rastreo y veamos si puedes dar caza a alguna de las bestias."] = 185,
				["Este es el desafío final al que tienes que enfrentarte. Llevamos semanas rastreando a una y matar a Sin'Dall. Tráeme su zarpa como prueba. Rastrearla no será una tarea fácil."] = 188,
				["Estás aprendiendo, $c. Probemos ahora tus habilidades con los felinos maduros. Mata a 10 tigres $c. Probemos ahora tus habilidades con los felinos maduros. Mata a 10 tigres de Tuercespina."] = 186,
			},
		},
		["Domina la pantera"] = {
			["Sir S. J. Erlgadin"] = {
				["Casi has demostrado ser un maestro cazador de panteras. Hay una pantera llamada Bhag'thera merodeando para matar a la gran Bhag'thera. ¡Tráeme el colmillo de Bhag'thera y conseguirás mi respeto!"] = 193,
				["Creo que podemos subir un poco el nivel. Si quieres demostrar que estás $gpreparado:preparada; para resulta tan fácil matar a esas panteras como a las más jóvenes que mataste antes."] = 191,
				["Si quieres ser parte de la partida de caza tan estupenda que Hemet ha reunido, preocupes. Veamos, para empezar, mata 10 panteras jóvenes. Rastrearlas es solo la mitad del desafío..."] = 190,
				["Y ahora vamos con lo difícil. Un verdadero cazador de panteras puede demostrar su habilidad 10 de estas bestias. Si te parece difícil rastrearlas, espera a intentar matar a una..."] = 192,
			},
		},
