		["El Libro de la Divinidad"] = {
			[""] = {
				["Un paladín debe reflejar en todas las cosas la Luz que complementa su fuerza. E un paladín como su fuerza en la batalla. Aprende esto ahora y nunca lo olvides."] = 1646,
				["Un paladín debe reflejar en todas las cosas la Luz que complementa su fuerza. El un paladín como su fuerza en la batalla. Aprende esto ahora y nunca lo olvides."] = 1642,
			},
			["Azar Martillopujante"] = 2997,
			["Brandur Martiyerro"] = 2999,
			["Duthorian Rall"] = {
				[""] = 1641,
				["Ahora, tu tarea, $n, es encontrar en Ventormenta a alguien que necesite ayuda. Alguien de hablando de tu camino y de lo que significa ser un paladín de la Luz."] = 1643,
				["Coge esto, $n. Se llama Símbolo de la Vida. Has demostrado ser paciente y $gcaritativo:caritativa; Si puedes ayudarle, volveremos a hablar. Pronto. Que la gloria de la Luz sea contigo."] = 1781,
			},
			["John Turner"] = {
				["Mi esposa y yo llevamos un orfanato en Ventormenta. En los últimos diez años hemos que mi mujer haga algo de ropa, podría por fin hacer un envío a casa."] = 1648,
				["Voy a empezar a hacer planes para volver pronto a casa. Espero que a Stephanie Stephanie le vaya bien en Ventormenta. Estoy deseando volver a verla. Hasta la próxima, $c."] = 1778,
			},
			["Lord Grisillo Quiebrasombras"] = 3000,
			["Muiredon Forjabatalla"] = {
				["Estábamos espiando a unos enanos Hierro Negro que se habían establecido en un búnker al aquí estoy. Narm necesita ayuda y no descansaré hasta que la consiga. ¿Puedes ayudarnos, $n?"] = 1783,
				["Ya'stoy viendo a mi mujer hinchándose d'orgullo. Más te vale ir yendo p'allá ya mismo. batalla cuando llegue el momento de luchar contra la Plaga y los Hierro Negro esos."] = 1785,
			},
			["Narm Faulk"] = 1784,
			["Stephanie Turner"] = {
				["Benditos sean, la mayoría de ellos han perdido a su familia en la última década... pudieras traerme paño de lino para que cosa ropa para los niños, me ayudarías mucho."] = 1644,
				["Llevaré esto a los niños hoy mismo. Cuídate, por favor. No encuentra una a menudo demostrado que los paladines de Ventormenta nunca vuelven la espalda a quienes los necesitan. Adiós."] = 1780,
			},
			["Tiza Forjabatalla"] = {
				[""] = 1645,
				["Ahora, tu tarea, $n, es encontrar en Forjaz a alguien que necesite ayuda. Alguien de la Luz. Esperaré tu regreso en el templo. Habrá otros paladines que necesiten mi guía."] = 1647,
				["Quiero que cojas esto, $n. Se llama Símbolo de la Vida. Has demostrado tener paciencia habla con él. Si puedes ayudarle, volveremos a hablar. Pronto. Que la Luz sea contigo."] = 1779,
			},
