			},
			["Elling Trias"] = {
				["Jorgen, viejo hijo de... Así que, ¿así es como va a ser, eh? Pues muy que yo te lo he pedido y te ayudará dándote toda la información que puedas."] = 1243,
				["Sí, ahora que lo pienso... Dashel... Dashel algo... ¿Cómo se llamaba? ¡PUÑO! Dashel Puñopiedra. Le tanto como sugieren estos papeles, entonces no va a darte ninguna información por voluntad propia."] = 1246,
				["Uno de mis contactos se retiró y se fue a Los Humedales, en la ciudad es. En los papeles no se dice nada sobre sus planes después de la captura."] = 1248,
			},
			["Jorgen"] = 1242,
			["Lady Jaina Valiente"] = 1267,
			["Mikhail"] = {
				["A principios de mes, todos los marineros de Kul Tiras reciben la paga y, generalmente, completamente leal a Valiente, pero si dejas caer el nombre de Elling, te ayudará... discretamente."] = 1264,
				["¿Dices que Elling te ha enviado? Bueno, pues entonces, la hospitalidad que te expresé, multiplícala quiero decir... Si yo fuera tú, haría algo para detenerle antes de que salga corriendo."] = 1249,
