		["El suero de la verdad"] = {
			["Boticario Faustin"] = {
				["Conozco el suero perfecto. Trata la verdad justo como la verdad debe ser tratada. Para profundidades de Desolace. En raras ocasiones, los gigantes enferman y desarrollan tumores. Hala, ¡en marcha!"] = 1383,
				["Todo procede según el plan, $n. Quiero que le entregues este suero de la verdad de la verdad a Zraedus el mortacechador. Él te indicará cómo administrarlo correctamente. ¡Ja, ja!"] = 1388,
			},
			["Mortacechador Zraedus"] = {
				["Nuestra fuerza expedicionaria fue enviada a bajo Azeroth a instancias de Varimathras. Mientras rastreábamos el Colabora con Faustin para preparar... un suero de la verdad para nuestro amigo de Rocal."] = 1372,
				["Tenemos que actuar con una cierta discreción. Después de todo, no puedes entrar ahí tal Recuerda que está en el Pantano de las Penas. Y mantén nuestra misión en secreto..."] = 1391,
