		["El tesoro de los Shen'dralar"] = 7462,
		["El tesoro del Atemporal"] = 8745,
		["El tesoro escondido del capitán Sanders"] = {
			[""] = {
				["Buscando en el barril descubres otro fragmento de pergamino. En este se puede leer: Desde los riscos del mar. Si buscas alrededor de la jarra encontrarás lo que estás buscando."] = 139,
				["Ciertamente, dentro de la Vieja jarra hay otra pista sobre el tesoro de Sander. La andando! ¡Nada directo hacia el Oeste hasta encontrar la isla con el cofre del tesoro!"] = 140,
				["Esto es lo que dice la siguiente pista: ¡Buen trabajo, compañero! Ahora tienes que ir de chimeneas a orillas del camino. Allí encontrarás un viejo barril con la siguiente pista."] = 138,
				["Si estás leyendo esto, el capitán Sanders estará sepultado bajo el agua. Así que mi la costa. ¡Encuentra el ancla y encontrarás mi baúl! Allí encontrarás también la siguiente pista."] = 136,
			},
		},
		["El tesoro sumergido"] = {
			["Doctor Draxlegauge"] = {
				["El tesoro lleva tanto tiempo en el fondo del mar que las gemas se han estooo, tengo importantes asuntos científicos que atender en tierra firme y seca… digo, pues eso."] = 666,
				["No hagamos esperar al capitán O'Breen. Querrá ver estas gemas el primero. A fin de que nos pillaran con su tesoro en las manos. Ahí va, $n, llévaselas a O'Breen."] = 668,
