		["El vudú debido"] = 609,
		["El vínculo"] = {
			["Carendin Halgar"] = {
				["Usando estos corazones, lanza un hechizo al Círculo de Invocación para abrir una puerta por vacío, y entonces te enseñaré el hechizo para invocarlo a tu antojo en el futuro."] = 1474,
				["¿Ves el Círculo de Invocación? Ahí es donde debes invocar a un abisario. Con la te explicaré el hechizo de invocación para que te ayude en el fin que persigas."] = 1471,
			},
			["Gakin el Presotenebra"] = {
				["Al recuperar mi gargantilla y vencer a Surena has demostrado ser, al menos, tan capaz Utiliza la magia de esta gargantilla en el Círculo de Invocación que está ahí abajo."] = 1689,
				["Utilizando el corazón del duramen, podrás lanzar un hechizo en el Círculo de Invocación de y lo devuelvas al vacío, vuelve a verme y te enseñaré a invocarlo y controlarlo."] = 1739,
			},
			["Ojo sangriento de Gan\\'rul"] = {
				["Lleva eso al círculo de invocación de la carpa de Neeru. Invoca a un súcubo hayas derrotado, devuélveme el colgante para que pueda decirle a Zankaja lo que ha pasado."] = 1513,
				["Verás que la tablilla contiene los glifos de invocación. Llévatela al círculo de la carpa los glifos de invocación y te enseñaré cómo ligar a la criatura a tu voluntad."] = 1504,
			},
