		["Elementales de agua"] = 601,
		["Elixir de agonía"] = {
			["Boticario Lydon"] = {
				["El nuevo elixir ya está listo para probar. Pero sería una pena malgastar una plaga un barril de cerveza Machacacanillas. Y cuando lo traigas nos pegaremos una buena fiesta, $n."] = 517,
				["Justo cuando pensaba que este sería otro día triste y sin alegría, me traes estas y ya estará listo. Llévale este compuesto de morrobarro al boticario a toda prisa, $N."] = 513,
				["Los guardias de la muerte tienen retenidos a varios granjeros. La suma ejecutora Darthalia sospechaba Coloca este barril contaminado en la alfombra de su cuarto. ¡Y que corra la plaga!"] = 524,
				["Un día más, un elixir más. Si por mí fuera, dejaría que esos ridículos humanos este del río y de Costasur. Tráeme seis flores de morrobarro para mi próximo elixir."] = 509,
			},
			["Maestro boticario Faranell"] = 515,
		},
		["Elixir del dolor"] = {
			["Boticario Lydon"] = {
				["Oh, $N. En Trabalomas todo está florecido y el aire es puro y fresco. No estupenda poción letal con sangre de puma. Tráeme un poco, verás qué bien lo pasaremos."] = 501,
				["¡No hay nada como el olor a sangre fresca! Ahora añadimos un poquito de esto suroeste. A ver qué le parece esta golosina a Stanley, el perrito del granjero Ray."] = 502,
			},
		},
		["Elixir del sufrimiento"] = {
			["Boticario Lydon"] = {
				["Otro maldito día en el Molino Tarren. Todo este aire puro me pone enfermo, $n. raro y difícil de encontrar. Nada más salir del Molino Tarren encontrarás osos y trepadores."] = 496,
				["Tardaré un momento en mezclar estos ingredientes para crear lo que yo llamo mi elixir lo que la Dama Oscura ha planeado tanto para los humanos como para la Plaga."] = 499,
			},
		},
