		["En guerra con la Cruzada Escarlata"] = {
			["Ejecutor Zygand"] = {
				["\"Los documentos del ejecutor Arren contienen exactamente todos los detalles que necesitamos para erradicar la de Rémol. Mata a Perrine, a 3 fanáticos y a 3 misioneros y regresa aquí."] = 370,
				["La Cruzada Escarlata ha estado atacando desde las ruinas de la torre situada al norte peligrosa. Mata a Melrache y a sus dos guardaespaldas en nombre de la Dama Oscura."] = 372,
				["Los documentos que el ejecutor Arren nos ha proporcionado son exactamente lo que necesitábamos para hasta la torre que encontrarás pasada la Hacienda Solliden y mata a 10 guerreros Escarlata."] = 427,
				["Seguimos en guerra y la Cruzada Escarlata se hace cada vez más fuerte. El informe Mata a Vachon y a 5 frailes Escarlata. ¡Será un duro golpe para la Cruzada!"] = 371,
