		["La Torre de Althalaxx"] = {
			["Balthule Golpesombra"] = {
				["Entiendo. Bien, si lo que dices es cierto, es el momento de actuar. Creo que protegido por muchos brujos poderosos, mucho más mortíferos que los que has afrontado hasta ahora."] = 1143,
				["Mi maestro, Delgren el Purificador es un paladín que ha ofrecido gentilmente su ayuda en del Bosque de Vallefresno. Debes apresurarte: la amenaza de la Facción Oscura crece cada hora."] = 967,
				["Por todo lo que has hecho, bien mereces una recompensa. Busca a Delgren y dile tu mano y que el Culto de la Facción Oscura ha sido derrotado y dispersado."] = 981,
				["Un grupo de brujos se ha instalado alrededor y dentro de la torre. Habría regresado no entres en la torre, los brujos que hay en ella son los más poderosos."] = 966,
			},
			["Centinela Elissa Brisa Estelar"] = 965,
			["Delgren el Purificador"] = {
				["Antes de enfrentarte a Athrikus, probablemente sería prudente que consultaras a Balthule. No me cabe atento en su observatorio de la torre y podría tener información sobre los últimos movimientos."] = 1167,
				["Ilkrud Magthrull. Sí, sé algo acerca de él. Es un poderoso brujo orco que mora menor y no he tenido que tratarlo pero, por lo visto, ha llegado su hora."] = 973,
				["La carta de Balthule es espantosa. Este culto de la Facción Oscura es una espina el secreto del poder del culto. Tráemela y podré descifrar el secreto de su interior."] = 970,
				["La letra de los orcos es un poco mejor que los garabatos de un niño. los sátiros bañados en sangre pueden ser perturbadores hasta para un $c curtido como tú."] = 1140,
			},
		},
