		["La batalla de Trabalomas"] = {
			["Suma Ejecutora Darthalia"] = {
				["El Registro de Trabalomas indica que la Mina Azur se encuentra bajo el control de un humano llamado Bonds. Elimina también a los mineros. Eso le enseñará a la Alianza."] = 539,
				["El ataque a las granjas del norte tiene aterrados a los lugareños. Excelente. Nuestros mortacechadores busca a los labriegos ocultos. Aniquílalos en el nombre de nuestra Dama Oscura. Puedes retirarte."] = 528,
				["He redactado una mención honorífica describiendo tu heroica actitud en combate para que el alto esta mención sellada a Varimathras; está en Entrañas. Ve con la frente muy alta, $c."] = 550,
				["Los humanos de Trabalomas han opuesto más resistencia de la esperada. Al parecer, el herrero de su almacén. Nos irá bien cuando terminemos con Trabalomas y pasemos a conquistar Costasur."] = 529,
				["Ponte firme cuando te dirijas a mí, $c. Estoy a las órdenes directas de Varimathras. Trabalomas. Asegúrate de que los propietarios, el granjero Ray y el granjero Getz, son ejecutados."] = 527,
				["Trabalomas está en ruinas y creemos que a punto de caer. Pero debemos mantenernos firmes más preciado documento, la Declaración de Trabalomas. Y ya que estás, saquea el registro civil."] = 532,
				["¿Enanos ayudando a los humanos? Malditas sean esas pequeñas y sucias bestias. Pondremos a prueba de esta batalla es asediar Dun Garok, $c. El capitán Ferrocolina, su líder, debe morir."] = 541,
			},
