				["Para empezar, deja que te cuente más sobre el cometido que debes realizar. Los druidas de vuelta. Cuando hayas completado tu tarea, te seguiré contando la historia que comenzó Tenaron."] = 929,
				["Sin embargo, no todo iba bien en Teldrassil. Corzocelada lo había planeado todo meticulosamente ya más poderosa de nuestras pozas. Llena una ampolla con agua de esta poza y tráemela."] = 934,
				["Sin la bendición de Alexstrasza la Protectora y Nozdormu el Atemporal, el crecimiento de Teldrassil a Darnassus. Entrégasela a Fandral Corzocelada, que se encuentra en la Arboleda de los Druidas."] = 935,
