		["La hermandad de los Defias"] = {
			["El Traidor de los Defias"] = 155,
			["Gryan Mantorrecio"] = {
				["La banda de desgraciados responsable de que las gentes de los Páramos de Poniente abandonaran Lago, en las Montañas Crestagrana, al este de Elwynn, y averigua todo lo que puedas."] = 65,
				["Me pregunto qué querría decir Wiley cuando habló de los Albañiles. Quizás fue un lapsus. este misterio. Si tienes problemas para encontrarlo, busca en el Cuartel, en el Casco Antiguo."] = 135,
				["Tenemos que descubrir la localización de la Ladronera Defias. $N, según los informes de mi Jango. Quiero que le captures. Si ofrece resistencia, mátalo y tráeme lo que esté llevando."] = 142,
				["Todavía hay una tarea que debes cumplir. Edwin VanCleef debe ser asesinado. Aunque me entristece una vez por todas. Tráeme la cabeza de ese villano cuando hayas terminado tu hazaña."] = 166,
			},
