		["La justicia del castigo"] = {
			["Jer\\'kai Tejeluna"] = {
				["Como ya te ha dicho Kindal, ella y yo llevaremos el conflicto a los Tótem cuando hayan sentido el dolor de las flechas de Kindal y el de tus armas."] = 2970,
				["Kindal y yo no tenemos aquí los medios para recompensar tu ayuda, pero no queremos nosotras estamos bien y dará crédito a tu historia. Ambas te damos las gracias, $N."] = 2972,
