		["La leche de la madre"] = 4866,
		["La leyenda de Kharan"] = 4342,
		["La leyenda de Korrak"] = 7181,
		["La leyenda de Stalvan"] = {
			[""] = {
				["Dentro de la caja encuentras varios objetos: reliquias familiares mohosas, unos trofeos de caza, un libros antiguos. Al fondo, debajo de un jarrón, descubres una página arrancada de un diario."] = 74,
				["En el viejo arcón encuentras una carta polvorienta sin enviar. En el viejo arcón encuentras una carta polvorienta sin enviar."] = 68,
			},
			["Alguacil Haggard"] = {
				["Cuando me mudé aquí había un fajo de pergaminos en el cofre de arriba. Empecé aunque está algo descolorida, podría interesarte mucho. Tráemela. Yo te ayudaré en lo que pueda."] = 75,
				["Sé de alguien que probablemente podrá ayudarte. Cuando yo comandaba la guardia de Ventormenta, iba de la zona. Enséñale esta página y escucha lo que te pueda decir sobre ella."] = 78,
			},
			["Comandante Althea Cerranegro"] = {
				["Estuve vigilando a ese asqueroso de Stalvan durante mucho tiempo. Si está página fue escrita y pídele que compruebe si la caligrafía coincide con la de la firma del registro."] = 80,
				["Stalvan Mantoniebla llevó una vida de depravación. Su mano sesgó innumerables vidas inocentes. Es, sin nos guió a este terrible descubrimiento. Gracias a ella, Villa Oscura ahora es más segura."] = 98,
			},
			["Custodio Folsom"] = 72,
			["Dependiente Daltry"] = {
				["Stalvan, ¿eh? Deja que consulte el registro. Stalvan... Stalvan... Veamos... ¡Ah! ¡Aquí está! Tengo un si consigues información más reciente sobre este tipo. Me gusta llevar los registros al día."] = 67,
				["¡Ay, ay! Esto se me debió de pasar la primera vez. En el registro, justo que se dirigía a la Posada Orgullo de León, en Villadorada. Quizás quieras comprobarlo, $n."] = 69,
				["¡Informa de inmediato a la comandante Ebonlocke de que las caligrafías coinciden, $N! ¡Sus sospechas la comandante Ebonlocke de que las caligrafías coinciden, $N! ¡Sus sospechas han resultado ser ciertas!"] = 97,
			},
			["Lady Eva"] = 66,
			["Tabernero Farley"] = 70,
			["Tabernero Smitts"] = 79,
		},
		["La limpieza de Raene"] = {
			[""] = 1055,
			["Cadáver de Teronis"] = 1023,
			["Krolg"] = {
				["Los elfos de la noche existen desde la noche de los tiempos pero su arrogancia elfos pero no deseo el mal de su estirpe, así que debemos vigilar la nuestra."] = 1045,
				["Vuelve a tu propia tribu y háblales de tu victoria aquí. Enséñales tu trofeo y y háblales de tu victoria aquí. Enséñales tu trofeo y date un baño de gloria..."] = 1046,
			},
			["Raene Correlobo"] = {
				["$N, un viejo amigo también está colaborando con las centinelas aquí en Vallefresno pero aún encontraba allí antes de que lo invadieran. Encuentra a mi amigo, $N, te lo ruego."] = 991,
				["Desafortunadamente, no estoy del todo segura de cuál era su intención. Si era cierto lo no estuviera bajo los efectos del musgovil. Empezaría la búsqueda al sureste del Lago Mystral."] = 1030,
				["Tendrás que investigar por tu cuenta pero según las notas de Teronis, parece que tu la gema contigo, Shael'dryn la necesitará si te va a ayudar a recrear la vara."] = 1024,
			},
			["Shael\\'dryn"] = {
				["Aquí tienes la vara completada, $N. Volver a construirla ha sido sencillo... encontrar el altar allí, coloca la vara en el interior del altar… el resto es magia. Je, je."] = 1028,
				["Ojalá tus nuevas fueran mejores. Raene tiene razón, he oído hablar de la creación de la carretera cerca de los límites de Frondavil... el baúl debería estar escondido por ahí."] = 1026,
				["Se entregó la última pieza de la vara a los druidas de Dor'danil para su no pensar en ello demasiado. Cuando encuentres la última pieza, tráemela y recompondré la vara."] = 1027,
				["Te sugiero que encuentres a Raene y les digas que la vara está recompuesta. Seguro que la vara está recompuesta. Seguro que sabrá aconsejarte sobre el siguiente paso. Suerte, $N."] = 1029,
			},
		},
		["La limpieza de Roca Oculta"] = 2877,
