		["La llama Sagrada"] = {
			["Rau Abiscorredor"] = 1197,
			["Zangen Pezuñapétrea"] = {
				["Llévale la ampolla con agua a Rau Abiscorredor en el Poblado Viento Libre en la encontrarás en el extremo sur de Los Baldíos. No me sorprendería que pudieras seguir ayudándonos."] = 1196,
				["Los centauros Galak de Las Mil Agujas custodian un artefacto desde el comienzo de sus Río Falfarren, al sur de la carretera principal, donde podrás llenar la ampolla de agua."] = 1195,
			},
