			["Profeta Plumacuervo"] = {
				["$c, ha llegado el momento; tu cuerpo crece en edad y en fuerza y tu usan en sus rituales. Regresa cuando hayas conseguido el suficiente para crear tu propia poción."] = 1519,
				["La sapta es una bebida que nos ayuda a vincular el espíritu a los elementos. Ve al lugar santo de los chamanes, hacia el este, y bebe allí la sapta."] = 1520,
