		["La llamada de los guardianes"] = 9247,
		["La llamada del agua"] = {
			[""] = {
				["$gDispuesto:Dispuesta; pareces para la prueba siguiente, $N. Paciencia en tus estudios has mostrado pero de Trinquete. La encontrarás en su cabaña de pesca. Que la Fortuna te sea favorable, $N."] = 2985,
				["Hay un destello de luz cuando pronuncias las últimas palabras del conjuro. Se desvanece el y la emoción embarga tus sentidos conforme se destruyen los espíritus corruptos que te rodean."] = 100,
				["Mucho tiempo ha pasado desde que a prueba te pusieron, $N. Paciencia en tus estudios Trinquete. La encontrarás en su cabaña de pesca. Que la Fortuna te sea favorable, $N."] = 2986,
			},
			["Islen Vident\\'aqua"] = {
				["Por la costa del Bosque de Argénteos, al oeste de El Sepulcro, verás un altar comunicar. Tráeme una prueba de haber completado la tarea y te recompensaré con un tótem."] = 63,
				["Si hay una lección que has de aprender acerca del agua, es esta: el agua más recóndito de los Baldíos del Sur. Los jabaespines la importunan constantemente en su hogar."] = 1530,
			},
			["Manifestación de agua menor"] = 96,
			["Salmuera"] = {
				["Hace mucho tiempo seguí a unos compañeros hasta las Laderas de Trabalomas. Nos defendimos de sagrado en un mar sin consagrar. Tráeme una muestra de esa agua en esta bota."] = 1536,
				["Islen tendrá una tarea más para ti antes de recompensarte con tu siguiente tótem. Sea de agua que te he dado. Ahora vete y encuéntrala. Volveremos a encontrarnos algún día."] = 220,
				["Para adquirir el conocimiento y ganarte la sapta, debes buscar solo las formas más puras de mi cabaña hay un estanque del preciado líquido. Llena este odre y vuelve aquí."] = 1535,
				["Toma esta bota y adéntrate en el frondoso bosque que los elfos de la noche Será el último componente que necesitarás antes de que te mande de nuevo con Islen."] = 1534,
			},
