			["Telf Joolam"] = {
				["La sapta de fuego está acabada. Ha llegado el momento de que afrontes la llama. vez le hayas derrotado, coloca sus ascuas ardientes en el blandón y enciende la antorcha."] = 1526,
				["Pero tú no has venido aquí a recibir lecciones de historia, ¿verdad? Has venido aquí Ardiente. Los encontrarás en una cueva que está sobre los barrancos del noreste de Cerrotajo."] = 1525,
