		["La parte derecha del amuleto de Lord Valthalak"] = {
			["Bodley"] = {
				["Ahora que tenemos lo que necesitamos, es hora de decidir a quién vas a invocar a salvo de los sicarios espectrales. Lo ejecutaron en presencia de su maestro, Ras Murmuhielo."] = 8992,
				["Los hermanos, Jarien y Sothos, decidieron unirse a la Cruzada Escarlata tras disolverse nuestra compañía Bastión Escarlata. En cualquier caso, nosotros... digo... tú, todavía puedes recuperar esa pieza del amuleto."] = 8991,
