				["Encuentras el cadáver de una tortuga marina que fue a encallarse a la Costa Oscura así, parece que quedan algunas muestras que podrían resultar útiles a Gwennyth Bly'Leggonde de Auberdine."] = 4732,
				["Hay muchos restos de tortugas marinas a lo largo de la costa. Esta en concreto el carruaje encuentras una caja con símbolos extraños. Quizás Gwennyth Bly'Leggonde de Auberdine sepa interpretarlos."] = 4725,
				["Hay otro grupo de restos de una tortuga marina encallada en la costa. Estos restos el carruaje encuentras una caja con símbolos extraños. Quizás Gwennyth Bly'Leggonde de Auberdine sepa interpretarlos."] = 4731,
			},
